from typing import List


def factorize(n: int) -> List[int]:
    if n <= 1:
        if n == 1:
            return []
        raise ValueError("Input must be a positive integer greater than 1")
    factors = []
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 1
    if n > 1:
        factors.append(n)
    return factors
